Voici un exemple de code pour un bot Discord avec une commande "bannir" à l'aide de Discord.js v14 :

```javascript
// Importez Discord.js v14
const { Client, GatewayIntentBits, InteractionType } = require('discord.js');

// Créez un objet de configuration pour le client Discord.js
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Connexion du client au Discord
client.on('ready', () => {
  console.log(`Bot Discord connecté en tant que ${client.user.tag}`);
});

// Écoutez les interactions slash
client.on('interactionCreate', async interaction => {
  if (!interaction.isChatInputCommand()) return;

  // Vérifiez la commande utilisée
  if (interaction.commandName === 'bannir') {
    // Vérifiez les permissions de l'utilisateur
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({ content: 'Vous n'avez pas la permission de bannir les utilisateurs.', ephemeral: true });
    }

    // Récupérez l'utilisateur à bannir
    const userToBan = interaction.options.getUser('utilisateur');

    // Vérifiez si l'utilisateur est sur le même serveur que le bot
    if (interaction.guild.members.me.hasPermission('BanMembers') && interaction.guild.members.me.id !== interaction.user.id) {
      if (!interaction.guild.members.me.permissionsIn(userToBan.voiceChannel).has('Connect')) {
        return interaction.reply({ content: 'Je ne peux pas bannir cet utilisateur car je n\'ai pas la permission de rejoindre ce salon vocal.', ephemeral: true });
      }
    } else {
      return interaction.reply({ content: 'Je ne peux pas bannir cet utilisateur car je ne suis pas sur ce serveur.', ephemeral: true });
    }

    // Bannissez l'utilisateur
    try {
      await interaction.guild.bans.create(userToBan.id);
      return interaction.reply({ content: `L'utilisateur ${userToBan.tag} a été banni.` });
    } catch (error) {
      console.error(error);
      return interaction.reply({ content: 'Une erreur est survenue lors du bannissement de l\'utilisateur.', ephemeral: true });
    }
  }
});

// Connexion du client au Discord
client.login(process.env.DISCORD_TOKEN);
```

Cette commande utilise la commande slash `bannir` et vérifie les permissions de l'utilisateur avant de bannir l'utilisateur ciblé. N'oubliez pas d'ajouter la commande `bannir` dans votre application Discord en utilisant le panneau de configuration de votre bot. N'oubliez pas non plus de remplacer `process.env.DISCORD_TOKEN` par votre propre token Discord. 

