Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <string>
#include <iostream>
#include <regex>

std::string convertMarkdownToHtml(const std::string& markdown) {
    std::string html;

    // Headers
    std::regex header_regex("^#{1,6}\\s(.*)$");
    std::smatch header_match;
    if (std::regex_match(markdown, header_match, header_regex)) {
        std::string header_level = std::to_string(header_match.size()) + "<";
        std::string header_text = header_match[1];
        html += "<h" + header_level + ">" + header_text + "</h" + header_level + ">\n";
    } else {
        html += markdown + "\n";
    }

    // Bold and Italic
    std::regex bold_regex("\\*([^*]+)\\*");
    std::regex italic_regex("([^_]*_([^_]*))|([^_]*__([^_]*))");
    std::string markdown_copy = markdown;
    while (std::regex_search(markdown_copy, bold_match, bold_regex)) {
        std::string bold_text = bold_match[1];
        html += "<strong>" + bold_text + "</strong>\n";
        markdown_copy = bold_match.suffix();
    }
    while (std::regex_search(markdown_copy, italic_match, italic_regex)) {
        std::string italic_text;
        if (italic_match.size() == 2) {
            italic_text = italic_match[1];
        } else {
            italic_text = italic_match[2];
        }
        html += "<em>" + italic_text + "</em>\n";
        markdown_copy = italic_match.suffix();
    }

    // Lists
    std::regex list_regex("^\\s*(\\d+\\.\\s)|(^\\s*-\\s)|(^\\s*\\d+\\s*\\.)\\s(.*)$");
    std::smatch list_match;
    while (std::regex_search(markdown, list_match, list_regex)) {
        std::string list_type;
        std::string list_text;
        if (list_match.size() == 1) {
            list_type = "<ul>\n";
        } else if (list_match.size() == 4) {
            list_type = (list_match[1].str().empty() ? "<ol>\n" : "<ul>\n");
            list_text = list_match[3];
        }
        html += list_type;
        std::string list_item;
        while (std::regex_search(list_text, list_item_match, std::regex("^\\s*(\\d+\\.\\s)|(^\\s*-\\s)|(^\\s*\\d+\\s*\\.)\\s(.*)$"))) {
            std::string list_item_type;
            std::string list_item_text;
            if (list_item_match.size() == 1) {
                list_item_type = "<li>";
            } else if (list_item_match.size() == 4) {
                list_item_type = (list_item_match[1].str().empty() ? "<li>" : (list_item_match[2].str().empty() ? "<li>" : "<li>"));
                list_item_text = list_item_match[3];
            }
            html += list_item_type + list_item_text + "</li>\n";
            list_text = list_item_match.suffix();
        }
        html += "</" + list_type + ">\n";
        markdown = list_match.suffix();
    }

    // Links
    std::regex link_regex("\\[([^\\]]*)\\]\\\\(([^\\)]*)\\)");
    while (std::regex_search(markdown, link_match, link_regex)) {
        std::string link_text = link_match[1];
        std::string link_url = link_match[2];
        html += "<a href=\"" + link_url + "\" target=\"_blank\">" + link_text + "</a>\n";
        markdown = link_match.suffix();
    }

    return html;
}

int main() {
    std::string markdown = "## Titre H2\n\nTexte en gras: *texte*\n\nTexte en italique: _texte_\n\nListe non-ordonnée:\n- élément 1\n- élément 2\n\nListe ordonnée:\n1. Élément 1\n2. Élément 2\n\nLien: [Texte du lien](https://example.com/)";
    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

