Voici un code de base en C utilisant la bibliothèque SDL2 :

```c
#include <stdio.h>
#include <stdlib.h>
#include <SDL2/SDL.h>

// Dimensions de la fenêtre
#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600

// Taille de la grille de jeu
#define GRID_SIZE 20

// Dimensions des images
#define SERPENT_WIDTH 16
#define SERPENT_HEIGHT 16
#define APPLE_WIDTH 16
#define APPLE_HEIGHT 16

// Nombre de cases du serpent
#define INIT_SNAKE_SIZE 3

// Directions du serpent
enum Direction {
    LEFT,
    RIGHT,
    UP,
    DOWN
};

// Structure du serpent
typedef struct {
    int x, y;
    int size;
    SDL_Texture *texture;
    enum Direction direction;
} Snake;

// Structure de la pomme
typedef struct {
    int x, y;
    SDL_Texture *texture;
} Apple;

// Fonction pour charger une image en tant que texture SDL
SDL_Texture *loadTexture(SDL_Renderer *renderer, char *path) {
    SDL_Texture *texture = NULL;
    SDL_Surface *surface = SDL_LoadBMP(path);

    if (surface != NULL) {
        texture = SDL_CreateTextureFromSurface(renderer, surface);
        SDL_FreeSurface(surface);
    }

    return texture;
}

// Fonction pour dessiner le serpent
void drawSnake(SDL_Renderer *renderer, Snake *snake) {
    SDL_Rect srcRect = {0, 0, SERPENT_WIDTH, SERPENT_HEIGHT};
    SDL_Rect destRect;

    for (int I = 0; I < snake->size; i++) {
        destRect.x = snake->x + (i * GRID_SIZE);
        destRect.y = snake->y;
        destRect.w = SERPENT_WIDTH;
        destRect.h = SERPENT_HEIGHT;

        SDL_RenderCopy(renderer, snake->texture, &srcRect, &destRect);
    }
}

// Fonction pour dessiner la pomme
void drawApple(SDL_Renderer *renderer, Apple *apple) {
    SDL_Rect srcRect = {0, 0, APPLE_WIDTH, APPLE_HEIGHT};
    SDL_Rect destRect;

    destRect.x = apple->x;
    destRect.y = apple->y;
    destRect.w = APPLE_WIDTH;
    destRect.h = APPLE_HEIGHT;

    SDL_RenderCopy(renderer, apple->texture, &srcRect, &destRect);
}

// Fonction pour dessiner le jeu complet
void drawGame(SDL_Renderer *renderer, Snake *snake, Apple *apple, int score) {
    SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
    SDL_RenderFillRect(renderer, NULL);

    drawSnake(renderer, snake);
    drawApple(renderer, apple);

    SDL_Rect scoreRect = {10, 10, 80, 20};
    SDL_Color scoreColor = {255, 255, 255};
    char scoreStr[16];
    sprintf(scoreStr, "Score: %d", score);

    SDL_Surface *scoreSurface = TTF_RenderText_Solid(NULL, scoreStr, scoreColor);
    SDL_Texture *scoreTexture = SDL_CreateTextureFromSurface(renderer, scoreSurface);
    SDL_FreeSurface(scoreSurface);

    SDL_Rect scoreDestRect = {10, 30, 80, 20};
    SDL_RenderCopy(renderer, scoreTexture, NULL, &scoreDestRect);
    SDL_DestroyTexture(scoreTexture);
}

// Fonction pour gérer le mouvement du serpent
void moveSnake(Snake *snake, enum Direction direction) {
    int headX = snake->x;
    int headY = snake->y;

    switch (direction) {
        case LEFT:
            headX -= GRID_SIZE;
            break;
        case RIGHT:
            headX += GRID_SIZE;
            break;
        case UP:
            headY -= GRID_SIZE;
            break;
        case DOWN:
            headY += GRID_SIZE;
            break;
    }

    snake->x = headX;
    snake->y = headY;
}

// Fonction pour gérer la collision entre le serpent et la pomme
void eatApple(Snake *snake, Apple *apple, int *score) {
    if (snake->x == apple->x && snake->y == apple->y) {
        snake->size++;
        *score += 10;

        int maxX = WINDOW_WIDTH / GRID_SIZE - 1;
        int maxY = WINDOW_HEIGHT / GRID_SIZE - 1;

        apple->x = rand() % (maxX + 1);
        apple->y = rand() % (maxY + 1);
    }
}

// Fonction pour gérer la collision entre le serpent et lui-même
int collideSnake(Snake *snake) {
    int headX = snake->x;
    int headY = snake->y;

    for (int I = 0; I < snake->size - 1; i++) {
        if (headX == snake->body[i].x && headY == snake->body[i].y) {
            return 1;
        }
    }

    return 0;
}

// Fonction pour gérer les interactions du joueur avec le serpent
void handleInput(SDL_Event *event, Snake *snake, Apple *apple, int *score) {
    switch (event->type) {
        case SDL_KEYDOWN:
            switch (event->key.keysym.sym) {
                case SDLK_LEFT:
                    if (snake->direction != RIGHT) {
                        snake->direction = LEFT;
                    }
                    break;
                case SDLK_RIGHT:
                    if (snake->direction != LEFT) {
                        snake->direction = RIGHT;
                    }
                    break;
                case SDLK_UP:
                    if (snake->direction != DOWN) {
                        snake->direction = UP;
                    }
                    break;
                case SDLK_DOWN:
                    if (snake->direction != UP) {
                        snake->direction = DOWN;
                    }
                    break;
            }
            break;
        case SDL_KEYUP:
            break;
    }

    moveSnake(snake, snake->direction);
    eatApple(snake, apple, score);
}

// Fonction pour gérer le temps
void tickClock(int *ticks, int *delay) {
    static int lastTick = 0;

    int now = SDL_GetTicks();

    if (now - lastTick >= *delay) {
        *ticks += 1;
        lastTick = now;
    }
}

// Fonction pour gérer l'interface utilisateur
void showUI(SDL_Renderer *renderer, int score) {
    SDL_Rect scoreRect = {10, 10, 80, 20};
    SDL_Color scoreColor = {255, 255, 255};
    char scoreStr[16];
    sprintf(scoreStr, "Score: %d", score);

    SDL_Surface *scoreSurface = TTF_RenderText_Solid(NULL, scoreStr, scoreColor);
    SDL_Texture *scoreTexture = SDL_CreateTextureFromSurface(renderer, scoreSurface);
    SDL_FreeSurface(scoreSurface);

    SDL_Rect scoreDestRect = {10, 30, 80, 20};
    SDL_RenderCopy(renderer, scoreTexture, NULL, &scoreDestRect);
    SDL_DestroyTexture(scoreTexture);
}

// Fonction principale
int main(int argc, char *argv[]) {
    SDL_Init(SDL_INIT_VIDEO);

    SDL_Window *window = SDL_CreateWindow(
        "Snake Game",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        WINDOW_WIDTH, WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN
    );

    SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    Snake snake = {
        .x = WINDOW_WIDTH / 2,
        .y = WINDOW_HEIGHT / 2,
        .size = INIT_SNAKE_SIZE,
        .texture = loadTexture(renderer, "snake.bmp"),
        .direction = RIGHT
    };

    Apple apple = {
        .x = rand() % ((WINDOW_WIDTH / GRID_SIZE) - 3) + 1,
        .y = rand() % ((WINDOW_HEIGHT / GRID_SIZE) - 3) + 1,
        .texture = loadTexture(renderer, "apple.bmp")
    };

    int score = 0;

    int ticks = 0;
    int delay = 150;

    while (true) {
        SDL_Event event;

        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                return 0;
            }

            handleInput(&event, &snake, &apple, &score);
        }

        tickClock(&ticks, &delay);

        if (ticks == 1 || collideSnake(&snake)) {
            SDL_DestroyTexture(snake.texture);
            snake.texture = loadTexture(renderer, "dead_snake.bmp");

            showUI(renderer, score);

            SDL_Delay(2000);

            snake.x = WINDOW_WIDTH / 2;
            snake.y = WINDOW_HEIGHT / 2;
            snake.size = INIT_SNAKE_SIZE;

            ticks = 0;
            delay = 150;

            score = 0;

            apple.x = rand() % ((WINDOW_WIDTH / GRID_SIZE) - 3) + 1;
            apple.y = rand() % ((WINDOW_HEIGHT / GRID_SIZE) - 3) + 1;
        }

        drawGame(renderer, &snake, &apple, score);

        SDL_RenderPresent(renderer);

        if (ticks == 4) {
            moveSnake(&snake, snake.direction);

            ticks = 0;
        } else {
            ticks++;
        }
    }

    SDL_DestroyTexture(snake.texture);
    SDL_DestroyTexture(apple.texture);

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);

    SDL_Quit();

    return 0;
}
