```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string wordToSearch; // mot à chercher dans le fichier
    int lineNumber = 0; // numéro de la ligne en cours
    int wordCount = 0; // nombre d'occurrences du mot à chercher

    // demander le mot à chercher
    cout << "Entrer le mot à chercher : ";
    cin >> wordToSearch;

    // ouvrir le fichier
    string fileName;
    cout << "Entrer le nom du fichier : ";
    cin >> fileName;
    ifstream file(fileName);

    // vérifier si le fichier a bien été ouvert
    if (!file) {
        cerr << "Impossible d'ouvrir le fichier " << fileName << endl;
        return 1;
    }

    // lire le fichier ligne par ligne
    string line;
    while (getline(file, line)) {
        lineNumber++;

        // chercher le mot dans la ligne
        size_t pos = line.find(wordToSearch);
        while (pos != string::npos) {
            wordCount++;
            pos = line.find(wordToSearch, pos + 1);
        }
    }

    // afficher le résultat
    cout << "Le mot \"" << wordToSearch << "\" a été trouvé " << wordCount << " fois dans " << lineNumber << " lignes du fichier " << fileName << endl;

    // fermer le fichier
    file.close();

    return 0;
}
